const $=id=>document.getElementById(id), colors=['#60ddc9','#a393ff','#ffbe73','#6db9ff','#fb8299','#cfdf6e'];
let data={runs:[]},live=false,selected='',busy=false,controlsRun='';
const finite=x=>typeof x==='number'&&Number.isFinite(x),ratio=(a,b)=>finite(a)&&finite(b)&&b>0?a/b:null;
const fmt=(v,percent=false)=>!finite(v)?'—':percent?`${(v*100).toFixed(1)}%`:new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(v);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const run=()=>data.runs.find(r=>r.id===selected),metric=(p)=>$('controller').value==='all'?p.game_metrics?.counters:p.controller_metrics?.[$('controller').value]?.counters;
const gr=(p,a,b)=>ratio(metric(p)?.[a],metric(p)?.[b]);
const charts=[];
function chart(target,title,note,lines,{percent=false,zero=true}={}){
 const node=document.createElement('article');node.className='chart';node.innerHTML=`<h3>${esc(title)}</h3><p>${esc(note)}</p>`;
 const valid=lines.filter(l=>l.points.some(p=>finite(p.x)&&finite(p.y)));
 if(!valid.length){node.innerHTML+='<div class="empty">Sin datos instrumentados para esta selección</div>';$(target).append(node);return;}
 const box=document.createElement('div');box.className='chart-canvas';const canvas=document.createElement('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label',title);canvas.textContent=title;box.append(canvas);node.append(box);$(target).append(node);
 charts.push(new Chart(canvas,{type:'line',data:{datasets:valid.map((line,i)=>({label:line.label,data:line.points.map(p=>({...p,y:finite(p.y)?p.y:null})),borderColor:line.color||colors[i%colors.length],backgroundColor:line.color||colors[i%colors.length],borderWidth:2,pointRadius:line.points.length<10?4:0,pointHitRadius:8,pointHoverRadius:5,spanGaps:false,tension:0}))},options:{responsive:true,maintainAspectRatio:false,animation:false,parsing:false,interaction:{mode:'nearest',intersect:false},plugins:{legend:{position:'bottom',labels:{color:'#a4b5c9',usePointStyle:true,boxWidth:8,font:{size:12}}},tooltip:{callbacks:{title:items=>`Partida ${fmt(items[0]?.parsed.x)}`,label:ctx=>`${ctx.dataset.label}: ${fmt(ctx.parsed.y,percent)}${ctx.raw.n!==undefined?` · n=${fmt(ctx.raw.n)}`:''}`}}},scales:{x:{type:'linear',title:{display:true,text:'Partidas entrenadas',color:'#a4b5c9'},ticks:{color:'#a4b5c9',maxTicksLimit:6},grid:{color:'#26374b55'}},y:{beginAtZero:zero,ticks:{color:'#a4b5c9',maxTicksLimit:5,callback:v=>fmt(v,percent)},grid:{color:'#26374b'}}}}}));
}
function selectedSeries(r){const smooth=$('smoothing').value==='200';let series=Object.entries(smooth?(r.smoothed_series||{}):($('stratum').value==='all'?(r.size_series||{}):(r.series||{})));if($('stratum').value!=='all')series=series.filter(([key])=>key===$('stratum').value);else if(smooth)series=series.filter(([key])=>['5x5-3','7x7-7','9x9-10','12x12-24','16x16-40','16x16-56'].includes(key));const n=Number($('window').value),cut=Number.isFinite(n)?(r.progress?.episode||0)-n:0;return series.map(([label,points])=>({label,points:points.filter(p=>p.episode>=cut)}));}
function linesFor(r,get){return selectedSeries(r).map(s=>({label:s.label,points:s.points.map(p=>({x:p.bucket_end??p.episode,y:get(p),n:p.policy_episodes}))}));}
function wilson(w,n){if(!n)return '—';const z=1.96,p=w/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return `${fmt(c-h,true)}–${fmt(c+h,true)}`;}
function render(){const r=run();if(!r)return;$('audit').hidden=r.id!=='curriculum-001';const p=r.progress||{},ep=p.episode??r.state?.episode??0,overall=r.overall_series||[];
 $('run-note').textContent=`${r.completed?'Corrida terminada':r.paused?'Corrida pausada':'Sin cierre registrado · consulta la fecha del último dato'} · ${r.config?.mode||'política original'} · ${$('smoothing').value==='200'?'Media móvil de hasta 200 partidas por dificultad exacta; n visible en cada punto. Vista general: seis dificultades de referencia.':`${r.bucket_size||'—'} partidas por ventana global; vista por tamaño con densidad variable.`} Cambio de comportamiento: ${p.behavior_schedule_start?`desde la partida ${p.behavior_schedule_start}`:'sin intervención registrada'}. Maestro programado: ${fmt(p.teacher_beta,true)}; exploración sin maestro: ${fmt(p.epsilon,true)}.`;
 $('stats').innerHTML=[['Partidas',`${fmt(ep)} / ${fmt(p.target??r.config?.episodes??50000)}`],['Clics acumulados',fmt(p.total_clicks??p.steps)],['Actualizaciones',fmt(p.updates)],['Memoria máxima',`${fmt((p.peak_rss_bytes_macos??p.peak_rss_bytes)/1024**3)} GB`]].map(([k,v])=>`<div class="stat"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('');
 for(const c of charts.splice(0))c.destroy();
 for(const id of ['eval-charts','train-charts','game-charts','compute-charts'])$(id).replaceChildren();
 const ev=(r.evaluations||[]).filter(e=>!['before/random','final/random','final/initial'].includes(e.kind)),latest=ev.at(-1),groups=[...new Set(ev.flatMap(e=>Object.keys(e.results||{})))].filter(k=>$('stratum').value==='all'||k===$('stratum').value);
 const evalLines=get=>groups.map(label=>({label,points:ev.filter(e=>e.results?.[label]).map(e=>({x:e.episode||0,y:get(e.results[label]),n:e.results[label].episodes}))}));
 chart('eval-charts','Win rate por dificultad','Victorias / partidas con decisiones; aperturas ganadas excluidas.',evalLines(x=>ratio(x.wins-(x.automatic_wins||0),x.episodes-(x.automatic_wins||0))),{percent:true});
 chart('eval-charts','Progreso del tablero','Fracción de casillas seguras reveladas al terminar.',evalLines(x=>x.mean_safe_fraction),{percent:true});
 $('eval-table').innerHTML=latest?Object.entries(latest.results||{}).filter(([k])=>groups.includes(k)).map(([k,x])=>{const n=x.episodes-(x.automatic_wins||0),w=x.wins-(x.automatic_wins||0);return `<tr><td>${esc(k)}</td><td>${w} / ${n}</td><td>${fmt(ratio(w,n),true)} · ${wilson(w,n)}</td><td>${fmt(x.mean_safe_fraction,true)}</td><td>${x.automatic_wins||0}</td></tr>`;}).join(''):'<tr><td colspan="5">Aún no hay una evaluación registrada para esta corrida.</td></tr>';
 $('eval-note').textContent=latest?`Última evaluación: partida ${latest.episode}, ${latest.kind||'periódica'}. Intervalos Wilson; compara entre corridas solo evaluaciones con el mismo protocolo y semillas.`:'El historial de entrenamiento no sustituye una evaluación fija.';
 const training=[['Win rate durante entrenamiento','Excluye aperturas ganadas. Puede incluir acciones del maestro.',p=>p.win_rate,true],['Casillas seguras reveladas','Incluye la apertura automática, igual que en evaluación.',p=>p.safe_fraction,true],['Retorno por partida','Recompensa original; las métricas del solver no la modifican.',p=>p.return,false],['Decisiones por partida','Longitud media; más clics no implica mejor estrategia.',p=>p.episode_steps,false],['Ayuda del maestro','Clics forzados por el maestro / clics totales.',p=>p.teacher_fraction,true]];
 training.forEach(([t,n,f,percent])=>chart('train-charts',t,n,linesFor(r,f),{percent}));
 // The realized split is a distribution of games, not a success metric.
 const shares=Object.entries(r.size_series||{}).map(([label,points])=>({label,points})).map(s=>({label:s.label,points:s.points.map(p=>({x:p.bucket_end??p.episode,y:ratio(p.episodes,overall.find(o=>o.bucket_end===p.bucket_end)?.episodes)}))}));
 chart('train-charts','Mezcla observada de tableros','Fracción de partidas de cada tamaño y minas por ventana.',shares,{percent:true});
 const game=[['Aprovecha casillas seguras','Elige una segura / oportunidades con al menos una demostrada.',p=>gr(p,'safe_taken','safe_opportunities'),true],['Clics en minas demostradas','Errores evitables / decisiones analizadas.',p=>gr(p,'proven_mine_clicks','analyzed_moves'),true],['Oportunidades seguras ignoradas','Errores lógicos detectados / decisiones analizadas.',p=>gr(p,'logical_errors','analyzed_moves'),true],['Cobertura de probabilidades exactas','Decisiones con enumeración exacta / decisiones analizadas.',p=>gr(p,'exact_moves','analyzed_moves'),true],['Riesgo inmediato elegido','Probabilidad media de mina en estados con cálculo exacto.',p=>gr(p,'chosen_risk_sum','exact_moves'),true],['Exceso de riesgo inmediato','Riesgo elegido menos mínimo disponible; no mide estrategia óptima.',p=>gr(p,'excess_risk_sum','exact_moves'),true],['Clics de riesgo mínimo','Entre decisiones con probabilidades exactas.',p=>gr(p,'minimum_risk_choices','exact_moves'),true],['Clics junto a pistas','Frontera / decisiones analizadas. Frecuencia, no calidad.',p=>gr(p,'frontier_clicks','analyzed_moves'),true],['Clics fuera de la frontera','Sin vecinos revelados / decisiones analizadas.',p=>gr(p,'interior_clicks','analyzed_moves'),true],['Preferencia por el borde','Borde geométrico / decisiones analizadas.',p=>gr(p,'border_clicks','analyzed_moves'),true],['Casillas abiertas por clic','Aperturas nuevas / clics medidos; excluye la apertura inicial.',p=>gr(p,'revealed_cells','reveal_observations'),false],['Frecuencia de expansión','Clics que revelan más de una casilla / clics medidos.',p=>gr(p,'flood_clicks','reveal_observations'),true],['Suerte en apuestas','Supervivencia observada menos esperada, solo probabilidades exactas.',p=>{const g=metric(p);return ratio(g?.exact_guess_survivals-g?.exact_guess_expected_survivals,g?.exact_guess_observations);},true],['Número de decisiones analizadas','Denominador de cobertura; verifica el tamaño de la muestra.',p=>metric(p)?.analyzed_moves,false]];
 game.forEach(([t,n,f,percent])=>chart('game-charts',t,n,linesFor(r,f),{percent}));
 chart('game-charts','Score neutral de finales 50/50','Episodios completos de todos los controladores. 0.5 en ambos resultados certificados; no altera el win rate.',linesFor(r,p=>ratio(p.game_metrics?.counters?.final_5050_neutral_score_sum,p.game_metrics?.counters?.final_5050_neutral_score_count)),{percent:true});
 chart('game-charts','Cobertura de finales 50/50','Finales certificados / episodios instrumentados con decisiones.',linesFor(r,p=>ratio(p.game_metrics?.counters?.final_5050_certified,p.game_metrics?.counters?.policy_episodes)),{percent:true});
 const whole=get=>[{label:r.id,points:overall.map((p,i)=>({x:p.bucket_end??p.episode,y:get(p,i)}))}];
 [['Pérdida de valores QR','Solo QR-DQN e híbrido.',p=>p.loss_qr],['Pérdida de imitación','Solo DAgger e híbrido.',p=>p.loss_teacher],['Norma del gradiente cerebral','Antes del recorte; no es calidad de la política.',p=>p.gradient_norm],['Memoria máxima','Máximo de la ejecución, en GB.',p=>finite(p.rss)?p.rss/1024**3:null],['Clics por segundo','Diferencia de clics / tiempo entre ventanas; incluye costos de ejecución.',(p,i)=>i?ratio(p.steps-overall[i-1].steps,p.training_seconds-overall[i-1].training_seconds):null],['Costo de instrumentación','Segundos de análisis adicional por partida medida.',p=>p.timing_metrics_seconds],['Exploración aleatoria programada','Probabilidad de exploración, condicionada a no usar maestro.',p=>p.epsilon],['Horas acumuladas','Tiempo reportado por el entrenador.',p=>finite(p.training_seconds)?p.training_seconds/3600:null]].forEach(([t,n,f])=>chart('compute-charts',t,n,whole(f)));
 renderControl(r);
}
function renderControl(r){$('control-fields').disabled=!live||!r.control_supported;const c=r.control||{},a=r.applied||{};
 $('control-state').textContent=!live?'Copia estática: controles deshabilitados.':!r.control_supported?'Esta corrida no admite cambios en vivo. Las nuevas corridas instrumentadas sí.':`Solicitada: ${c.mode||'scheduled'}, revisión ${c.revision||0}. Adoptada: ${a.mode||'sin confirmación'}, revisión ${a.revision??'—'}${a.episode!==undefined?`, desde la partida ${a.episode}`:''}.${r.completed?' Se guardará para una futura reanudación.':''}`;
 if(controlsRun!==r.id){controlsRun=r.id;const weights=c.weights||[1,1,1,1,1,1];$('weights').innerHTML=['5×5 / 3 minas','7×7 / 7 minas','9×9 / 10 minas','12×12 / 24 minas','16×16 / 40 minas','16×16 / 56 minas'].map((l,i)=>`<label>${l}<input type="number" min="0" step="any" required data-weight="${i}" value="${weights[i]}"></label>`).join('');}}
async function load(){if(busy)return;busy=true;try{let response=await fetch('./api/dashboard',{cache:'no-store'});if(!response.ok)throw Error('API no disponible');data=await response.json();live=true;}catch(err){if(!data.runs.length){try{const response=await fetch('./data/dashboard-snapshot.json');if(!response.ok)throw err;data=await response.json();}catch(e){$('connection').textContent='No se pudo cargar el historial';$('run-note').textContent=String(e.message);busy=false;return;}}live=false;}
 $('connection').textContent=`${live?'Local · actualizado':'Copia estática'} ${new Date(data.generated_at).toLocaleTimeString('es-MX')}`;
 const ids=data.runs.map(r=>r.id);if(!ids.includes(selected))selected=ids.includes('curriculum-001')?'curriculum-001':ids[0];const categories=[['Corridas principales',r=>!/(?:smoke|threaded|pilot)/i.test(r.id)],['Pilotos cortos',r=>/pilot/i.test(r.id)],['Pruebas técnicas',r=>/(?:smoke|threaded)/i.test(r.id)&&!/pilot/i.test(r.id)]];
 $('run').innerHTML=categories.map(([label,test])=>{const rows=data.runs.filter(test);return rows.length?`<optgroup label="${label}">${rows.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.id)}</option>`).join('')}</optgroup>`:'';}).join('');updateStrata();render();busy=false;}
function updateStrata(){const old=$('stratum').value;const keys=Object.keys(run()?.series||{}).sort((a,b)=>parseInt(a)-parseInt(b)||a.localeCompare(b));$('stratum').innerHTML='<option value="all">Todas · separadas por tamaño</option>'+keys.map(k=>`<option>${esc(k)}</option>`).join('');$('stratum').value=keys.includes(old)?old:'all';}
async function request(mode,weights){if(!live||!run()?.control_supported)throw Error('Esta corrida no permite cambiar la mezcla desde aquí.');if(!Array.isArray(weights)||weights.length!==6||weights.some(x=>!finite(x)||x<0)||!weights.some(x=>x>0))throw Error('Escribe seis pesos no negativos, con al menos uno positivo.');const response=await fetch('./api/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({run_id:selected,mode,weights})});const result=await response.json();if(!response.ok)throw Error(result.error||'Solicitud rechazada');$('control-message').textContent=`Solicitud ${result.revision} guardada. Esperando adopción al iniciar otra partida.`;await load();return result;}
$('control-form').onsubmit=async e=>{e.preventDefault();try{await request('manual',[...document.querySelectorAll('[data-weight]')].map(n=>Number(n.value)));}catch(err){$('control-message').textContent=err.message;}};
$('scheduled').onclick=async()=>{try{await request('scheduled',[1,1,1,1,1,1]);}catch(err){$('control-message').textContent=err.message;}};
$('run').onchange=()=>{selected=$('run').value;updateStrata();render();};for(const id of ['stratum','window','controller','smoothing'])$(id).onchange=render;$('refresh').onclick=load;
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mosca-entrenamientos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
await load();setInterval(()=>{if(!document.hidden)load();},60000);
if(document.modelContext?.registerTool){const abort=new AbortController();window.addEventListener('pagehide',()=>abort.abort(),{once:true});for(const tool of [
{name:'get_training_dashboard',description:'Read the loaded training summaries and available runs; no training changes.',annotations:{readOnlyHint:true},inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>({live,selected,runs:data.runs.map(r=>({id:r.id,episode:r.progress?.episode,control_supported:r.control_supported,evaluations:r.evaluations?.length})),smoothing:$('smoothing').value,series:selectedSeries(run()).map(s=>({label:s.label,lastN:s.points.at(-1)?.episodes})),charts:document.querySelectorAll('.chart').length,renderer:Chart.version,activeCharts:charts.length,groups:[...$('run').querySelectorAll('optgroup')].map(g=>({label:g.label,runs:[...g.children].map(o=>o.value)}))})},
{name:'select_training_run',description:'Select a run and optional exact difficulty in the visible dashboard. Does not change training.',annotations:{readOnlyHint:false},inputSchema:{type:'object',properties:{run_id:{type:'string'},stratum:{type:'string'}},required:['run_id'],additionalProperties:false},execute:input=>{if(!data.runs.some(r=>r.id===input.run_id))throw Error('Unknown run');const r=data.runs.find(r=>r.id===input.run_id);if(input.stratum&&input.stratum!=='all'&&!r.series?.[input.stratum])throw Error('Unknown stratum');selected=input.run_id;$('run').value=selected;updateStrata();$('stratum').value=input.stratum||'all';render();return {selected,stratum:$('stratum').value};}}
])try{await document.modelContext.registerTool(tool,{signal:abort.signal});}catch(e){console.warn('Dashboard tool unavailable',e.message);}}
